gcode_macro _FIND_POINT.gcode:
{% set bm = printer.bed_mesh %}
AUTOZ_CHECK
SET_GCODE_VARIABLE MACRO=_AUTOZ_STATE VARIABLE=deltas VALUE="[]"
SET_GCODE_VARIABLE MACRO=_AUTOZ_STATE VARIABLE=passed VALUE=False
SET_GCODE_VARIABLE MACRO=_TEST_POINT VARIABLE=temp_z_offset VALUE=0.0
{% if not bm.profile_name or not bm.probed_matrix %}
_AUTOZ_ABORT MSG="AutoZ FAIL: no saved mesh is loaded."
{% elif 'xyz' not in printer.toolhead.homed_axes %}
_AUTOZ_ABORT MSG="AutoZ FAIL: printer must be homed by START_PRINT first."
{% else %}
{% set ny = bm.probed_matrix|length %}
{% set nx = bm.probed_matrix[0]|length %}
{% if nx < 5 or ny < 5 %}
_AUTOZ_ABORT MSG="AutoZ FAIL: mesh needs at least five points per axis."
{% else %}
{% set dx = (bm.mesh_max[0] - bm.mesh_min[0]) / (nx - 1) %}
{% set dy = (bm.mesh_max[1] - bm.mesh_min[1]) / (ny - 1) %}
{% set xa = ((nx - 1) // 4)|int %}
{% set xb = ((nx - 1) // 2)|int %}
{% set xc = (((nx - 1) * 3) // 4)|int %}
{% set ya = ((ny - 1) // 4)|int %}
{% set yb = (((ny - 1) * 3) // 4)|int %}
{% set nodes = [(xa, ya), (xb, ya), (xc, ya), (xa, yb), (xb, yb), (xc, yb)] %}
{% set pz = printer.configfile.settings.probe.z_offset|float %}
{% set et = printer['gcode_macro _START_PRINT'].zextruder_temp|float %}
{% set bt = printer['gcode_macro _START_PRINT'].zbed_temp|float %}
RESPOND PREFIX=info MSG="AutoZ starting six-point mesh-relative check."
_ORIG_CLEAR_NOZZLE EXTRUDER_TEMP={et} BED_TEMP={bt}
{% for ix, iy in nodes %}
{% set x = bm.mesh_min[0] + ix * dx %}
{% set y = bm.mesh_min[1] + iy * dy %}
{% set expected = (bm.probed_matrix[iy][ix]|float) + pz %}
_AUTOZ_PROBE I={loop.index} X={x} Y={y} EXPECTED={expected}
{% endfor %}
_AUTOZ_FINISH
_AUTOZ_REQUIRE_PASS
_STOP_FAN
{% endif %}
{% endif %}

gcode_macro _PROBE_POINT.gcode:
{% set x = params.X|default(0)|float %}
{% set y = params.Y|default(0)|float %}
{% set z = params.Z|default(0)|float %}

{% set klipper13 = printer.save_variables.variables['klipper13']|default(0) | int %}
{% if klipper13 == 0 %}
{% set z_offset_klipper = printer.configfile.settings.probe.z_offset|default(0.0)|float %}
{% set zprobe = printer.probe.last_z_result %}
{% else %}
{% set z_offset_klipper = 0.0|float %}
{% set zprobe = printer.probe.last_probe_position.z %}
{% endif %}

{% if not find %}
_G28
M400
_TEST_MIN_MAX

{ action_respond_info("X: %.4f\tY: %.4f\tZ: %.4f" | format(x, y, z + z_offset_klipper)) }

SAVE_GCODE_STATE NAME=_probe_point
G1 X{x} F6000
G1 Y{y} F6000
M400

LOAD_CELL_TARE
