RESPOND PREFIX="info" MSG="Bed temperature: {bed_temp}"

{% if zprint_leveling == 0 %}
{% if force_kamp == True %}
RESPOND PREFIX="info" MSG="KAMP: enabled"
{% else %}
RESPOND PREFIX="info" MSG="KAMP: disabled"
